const WeatherScreen: React.FC = () => {
  const { theme, themeMode } = useTheme();
  const styles = useStyles();
  const sampleUi = useSampleUi();

  const { getValue } = useGlobalContext();
  const [expand, setExpand] = useState<string>('');

  const renderSampleUi = () => (
    <View style={styles.container}>
      <Text>Sample UI Components:</Text>
      <ScrollView
        horizontal
        showsHorizontalScrollIndicator={false}
        contentContainerStyle={styles.carouselContainer}
      >
        {sampleUi.map((item) => (
          <ActionButton
            key={item.id}
            size="xSmall"
            title={item.id}
            onPress={() => setExpand(expand === item.id ? '' : item.id)}
            style={styles.actionButton}
          />
        ))}
      </ScrollView>
      <Spacer height={theme.Size.vs(20)} />
      {sampleUi
        .filter((x) => x.id === expand)
        .map((item) => {
          return item.renderChild(item.id);
        })}
    </View>
  );

  return (
    <ScrollView>
      <View style={styles.container}>
        <Text>ThemeMode: {themeMode}</Text>
        <WeatherSearch />
        <WeatherInfo />
      </View>
      {renderSampleUi()}
    </ScrollView>
  );
};

const useStyles = createStyles((theme) => ({
  container: {
    margin: 20,
  },
  carouselContainer: {
    paddingHorizontal: 10,
  },
  actionButton: {
    margin: theme.Size.mvs(2),
  },
  gradientContainer: {
    padding: 20,
    display: 'flex',
    justifyContent: 'flex-end',
    alignItems: 'center',
    height: theme.Size.vs(148),
  },
  gradientOverlay: {
    backgroundColor: theme.Colors.Background.White,
    opacity: 0.8,
  },
}));

export default WeatherScreen;

