import { BottomSheet, Text, FormInput, ActionButton, Spacer, RadioButton, SearchBar, Theme, useTheme, SearchBarFunc } from '@core/ui';
import { FlatList, ScrollView, TouchableOpacity, View } from 'react-native';
import useCSS from '@src/presentation/style';
import { IBranch } from '@src/domain/entities/common/branch';
import { useTranslation } from 'react-i18next';
import { useEffect, useRef, useState } from 'react';

interface Props {
    data: IBranch[];
    selected: IBranch | string;
    onSelect: (item: IBranch) => void;
}

const ContentBranch: React.FC<Props> = ({ data = [], selected, onSelect, ...props }) => {
    const css = useCSS();
    const { theme } = useTheme();
    const { t } = useTranslation(['common']);
    const handleSelected = (item: IBranch) => {
        if (searchRef) {
            searchRef.current?.reset();
        }
        onSelect?.(item);
    };
    const [textSearch, setTextSearch] = useState('');
    const searchRef = useRef<SearchBarFunc>(null);
    const [listDataSearch, setListDataSearch] = useState<IBranch[]>([]);

    const getChecked = (item: IBranch) => {
        if (typeof selected === 'string') {
            return item.branchId === selected;
        } else if (item.branch) {
            return item.branch === selected.branch;
        } else if (item.branchId) {
            return item.branchId === selected.branchId;
        } else {
            return false;
        }
    };
    const handleSearch = (text: string) => { setListDataSearch(data.filter((item) => item.branchName?.toLowerCase().includes(text.toLowerCase()))); };
    useEffect(() => {
        if (textSearch === '') {
            setListDataSearch(data);
        }
        let debounceSearch = setTimeout(() => {
            handleSearch(textSearch);
        }, 300);
        return () => {
            clearTimeout(debounceSearch);
        };
    }, [textSearch]);
    useEffect(() => {
        setListDataSearch(data);
    }, [data]);
    return (
        <>
            <View>
                {/* <FormInput value='' onChange={() => { }} placeholder={t('search')} /> */}
                <SearchBar
                    ref={searchRef}
                    style={{ marginVertical: theme.Size.Vertical.Base }}
                    onSearch={setTextSearch} />
            </View>
            <Spacer height={16} />
            <FlatList
                data={listDataSearch}
                keyboardShouldPersistTaps='handled'
                renderItem={({ item, index }) => (
                    <TouchableOpacity key={item?.branch} onPress={() => handleSelected(item)}>
                        {index > 0 ? <View style={[css.border_t_1, css.border_t_neutral_300]} /> : null}
                        <View style={[css.pv_regular, css.mv_small, css.row, css.items_center]}>
                            <View style={[css.flex_1]}>
                                <Text style={[css.text_subheadline]}>{item.branchName}</Text>
                                {/* <Text>{item?.branchAddress || ''}</Text> */}
                            </View>
                            <RadioButton text='' onPress={() => undefined} size='large' checked={getChecked(item)} />
                        </View>
                    </TouchableOpacity>
                )}
                keyExtractor={(item, index) => `key-${item.branch}-${index}`}
            // style={[{ maxHeight: '70%' }]}
            />
        </>
    );
};

export default ContentBranch;
