import { ActionButton, createStyles, GradientButton, Theme, useTheme } from '@core/ui';
import { useDispatch } from '@src/lib/redux';
import React from 'react';
import { Image, ImageBackground, SafeAreaView, ScrollView, TouchableOpacity, View } from 'react-native';
import { Text, LoadingView, LoadingBlockerView } from '@core/ui';
import useCSS from '@src/presentation/style';
import moment from 'moment';
import { useNavigation } from '@react-navigation/native';
import { MainStackNavigationProp } from '@src/presentation/navigation/MainNavigator';
import { useTranslation } from 'react-i18next';
import getImg from '@src/utils/getImg';
import { SectionField, sectionFieldProps } from '../register_confirm/components/sectionField';
import { useSelector } from 'react-redux';
import { selectLoanDemandData, selectLoanDemandResponse } from '../register_confirm/redux/selector';
import { CURRENCY } from '@src/utils/constants';
import { formatMoney } from '@src/utils/currency';
import Clipboard from '@react-native-clipboard/clipboard';

const RegisterResultScreen = () => {
    const css = useCSS();
    const styles = useStyles();
    const { theme } = useTheme();
    const dispatch = useDispatch();
    const navigation = useNavigation<MainStackNavigationProp>();
    const { t } = useTranslation(['module_register']);
    const { globalId, phoneNumber, emailAddress, sex, consultantId, loanAmount, monthlyIncome, loanPurpose, collateral, loanMethod, repaymentMethod, branchId, loanTerm, expectedInterestRate, address, clientNo, clientName, birthDate, wardId, wardName, provinceId, provinceName, districtId, districtName } = useSelector(selectLoanDemandData);
    const loanDemandResponse = useSelector(selectLoanDemandResponse)
    const resultInfo: sectionFieldProps[] = [
        {
            id: 'loanAmount',
            title: t('screen_result.loanAmount'),
            divider: false,
            isRequired: true,
            value: loanAmount ? (formatMoney(loanAmount) + ' ' + CURRENCY) : '',
            showArrow: false,
        },
        {
            id: 'loan_term',
            title: t('screen_result.loanTerm'),
            divider: true,
            // fn: () => { setShowBottomSheetSliderLoanTerm(true) },
            isRequired: true,
            value: `${(loanTerm) ? (String(loanTerm) + ' ' + t('screen_confirm.loan_info.unit_year')) : ''}`,
            showArrow: false,
            allowEdit: false
        },

        {
            id: 'consultId',
            title: t('screen_result.consultId'),
            divider: true,
            // fn: () => {
            //     setShowBottomSheetInputHDCode(true);
            // },
            value: consultantId || ' ',
            showArrow: false,
            allowEdit: false
        },
        {
            id: 'transactionId',
            title: t('screen_result.transactionId'),
            divider: true,
            fn: () => { Clipboard.setString(String(loanDemandResponse?.data?.transactionNo)) },
            isRequired: true,
            value: loanDemandResponse?.data?.transactionNo ? String(loanDemandResponse?.data?.transactionNo) : ' ',
            showArrow: Boolean(loanDemandResponse?.data?.transactionNo),
            allowEdit: true,
            icon: '/assets/images/icons/Icon_copy.png',
            iconStyle: { width: theme.Size.Horizontal.xLarge, height: theme.Size.Vertical.xLarge }
        }]
    return (
        <ImageBackground source={getImg('/assets/images/bg/bg_body.jpg')} style={[css.flex_1]}>
            <SafeAreaView style={[css.flex_1]}>
                {/* <LoadingBlockerView containerStyle={{ backgroundColor: 'rgba(255,255,255,0.5)', zIndex: 100000 }} /> */}
                <ScrollView contentContainerStyle={[css.flex_1]}>
                    <View style={[css.p_medium, css.flex_1]}>
                        <View >
                            <Image
                                source={getImg('/assets/images/fire_work.png')}
                                style={[{ width: theme.Scaling.ms(100), height: theme.Scaling.vs(100), resizeMode: 'cover', aspectRatio: '1/1' }, css.pb_base]}
                            />
                            <Text style={[theme.Typography.Title200.Semibold, css.pb_base]}>{t('screen_result.title')}</Text>
                            <Text style={[theme.Typography.TextCaption100.Regular, css.pb_base]}>{moment().format('hh:mm DD/MM/YYYY')}</Text>
                            <Text style={[theme.Typography.TextSubheadline.Regular, css.pb_base]}>
                                {`${t('screen_result.desc_prefix')} `}<Text style={{ fontWeight: theme.FontWeight.bold }}>{clientName}</Text> {` ${t('screen_result.desc_suffix')}`}
                            </Text>
                            <View style={[css.pv_medium, { ...styles.sectionWrapper }]}>
                                {resultInfo.map((item, index) => (
                                    <SectionField key={index} title={item.title} render={item.render} divider={item.divider} fn={item?.fn} value={item?.value} showArrow={item?.showArrow} allowEdit={item?.allowEdit} icon={item.icon} iconStyle={item.iconStyle} />
                                ))}
                            </View>
                        </View>
                        <View style={{ marginTop: 'auto' }}>
                            <GradientButton gradientProps={{ type: 'primary' }} title={t('screen_result.button')} onPress={() => { navigation.navigate('products') }} />
                        </View>
                    </View>
                </ScrollView>
            </SafeAreaView>
        </ImageBackground>
    );
};

const useStyles = createStyles((theme: Theme) => {
    return {
        sectionWrapper: {
            borderWidth: 1,
            borderColor: theme.Colors.Border.Neutral300,
            overflow: 'hidden',
            borderRadius: theme.BorderRadius.md,
            backgroundColor: theme.Colors.Background.White,
            marginTop: theme.Size.Vertical.Medium,
            // marginHorizontal: theme.Size.Horizontal.Medium
        },
    };
});

export default RegisterResultScreen;
