import { createSlice } from '@reduxjs/toolkit';
import { Data } from '@src/domain/entities/loan_product/product_status';
import { fetchProductStatus } from './thunk';

interface ProductStatusState {
    data: Data | null;
    status: 'idle' | 'loading' | 'succeeded' | 'failed';
    error: string | null;
}

const initialState: ProductStatusState = {
    data: null,
    status: 'idle',
    error: null,
};

const productStatusSlice = createSlice({
    name: 'productStatus',
    initialState,
    reducers: {
        resetProductStatus: (state) => {
            state.data = null;
            state.error = null;
            state.status = 'idle';
        },
    },
    extraReducers: (builder) => {
        builder
            .addCase(fetchProductStatus.pending, (state) => {
                state.status = 'loading';
                state.error = null;
            })
            .addCase(fetchProductStatus.fulfilled, (state, action) => {
                state.status = 'succeeded';
                state.data = action.payload.data;
            })
            .addCase(fetchProductStatus.rejected, (state, action) => {
                state.status = 'failed';
                state.error = action.error.message ?? 'Failed to search product status';
            });
    },
});

export default productStatusSlice;
