import {
    View,
    TextInput,
    TextInputProps,
    StyleProp,
    Pressable,
    ViewStyle,
} from 'react-native';
import React, {
    forwardRef,
    useEffect,
    useMemo,
    useState,
    useImperativeHandle,
    useRef,
    JSX,
} from 'react';

import Animated, {
    FadeIn,
    FadeOut,
    interpolate,
    useAnimatedStyle,
    useSharedValue,
    withTiming,
} from 'react-native-reanimated';
import { SvgExtendProps } from '*.svg';
import { createStyles, ICheck, ISolidDelete1, IWarningCircle, Text, useTheme } from '@core/ui';
// import { ICheck, ISolidDelete1, IWarningCircle } from '../../assets';
// import { createStyles, useTheme } from '../../theme';

export const enum INPUT_STATUS {
    DEFAULT = 'default',
    ERROR = 'error',
    SUCCESS = 'success',
}

export const enum MODE {
    EDITABLE = 'editable',
    DISABLED = 'disabled',
    VIEW_ONLY = 'viewOnly',
}

interface MaterialTextInputProps extends TextInputProps {
    subText?: string;
    label?: string;
    containerStyle?: StyleProp<ViewStyle>;
    inputStyle?: StyleProp<ViewStyle>;
    onPressIconError?: () => void;
    onPressIconSuccess?: () => void;
    rightIcon?: () => JSX.Element;
    textLabelStyle: StyleProp<ViewStyle>;
    infoState: INPUT_STATUS;
    allowToClear?: boolean;
    mode?: MODE;
    errorIcon?: React.FC<SvgExtendProps>;
    errorIconColor?: string;
}

export interface MaterialTextInputPropsMethod {
    clearValue: () => void;
}

const DURATION = 200;

const CurrencyInput = forwardRef<
    MaterialTextInputPropsMethod | null,
    Partial<MaterialTextInputProps>
>((props, ref) => {
    const { theme } = useTheme();

    const styles = useStyles();

    const LABEL_BIG_FONT = theme.Size.ms(20);
    const LABEL_SMALL_FONT = theme.Size.ms(12);
    const LABEL_BIG_LINE_HEIGHT = theme.Size.ms(28);
    const LABEL_SMALL_LINE_HEIGHT = theme.Size.ms(16);
    const LABEL_INIT_POSITION = theme.Size.ms(0);
    const LABEL_TRANSFORM_POSITION = theme.Size.ms(-16);

    const {
        value,
        subText,
        label,
        containerStyle,
        inputStyle,
        onPressIconError,
        onPressIconSuccess,
        infoState = INPUT_STATUS.DEFAULT,
        allowToClear = true,
        rightIcon,
        mode = MODE.EDITABLE,
        errorIcon,
        errorIconColor,
    } = props || {};
    const activeColor = theme.Colors.Main.Red;
    const [isFocus, setIsFocus] = useState<boolean>(false);
    const [inputValue, setInputValue] = useState<string | undefined>();

    const inputRef = useRef<TextInput>(null);

    const isTextInputFocus = useSharedValue(0);
    const inputColor = useSharedValue(theme.Colors.Text.Neutral500);
    const subTextColor = useSharedValue(theme.Colors.Text.Neutral600);
    const hasValue = !!inputValue || !!value;

    const onBlur = (e: any) => {
        setIsFocus(false);
        inputColor.value = inputState[infoState].color;
        props.onBlur?.(e);
        if (!value && !inputValue) {
            isTextInputFocus.value = withTiming(0, { duration: DURATION });
        }
    };

    const onFocus = (e: any) => {
        props.onFocus?.(e);
        setIsFocus(true);
        isTextInputFocus.value = withTiming(1, { duration: DURATION });
        inputColor.value = activeColor;
    };

    const onClear = () => {
        if (props?.onChangeText) {
            props.onChangeText('');
        }
        setInputValue('');
    };

    const handleOnChangeText = (text: string) => {
        if (inputColor.value !== activeColor) {
            inputColor.value = activeColor;
        }
        if (typeof props?.onChangeText === 'function') {
            props?.onChangeText(text);
        }

        setInputValue(text);
    };

    useImperativeHandle(
        ref,
        () => ({
            clearValue: () => {
                onClear();
            },
            focus: () => {
                inputRef.current?.focus();
            },
            blur: () => {
                inputRef.current?.blur();
            },
        }),
        []
    );

    const inputState = {
        [INPUT_STATUS.DEFAULT]: {
            color: theme.Colors.Stroke.Dark10,
            rightIcon: ISolidDelete1,
            iconColor: theme.Colors.Text.Neutral600,
            onPressIcon: onClear,
            subTextColor: theme.Colors.Text.Neutral500,
        },
        [INPUT_STATUS.ERROR]: {
            color: theme.Colors.Text.Error,
            rightIcon: errorIcon || IWarningCircle,
            onPressIcon: onPressIconError,
            iconColor: errorIconColor || theme.Colors.Text.Error,
            subTextColor: theme.Colors.Text.Error,
        },
        [INPUT_STATUS.SUCCESS]: {
            color: theme.Colors.Stroke.Dark10,
            rightIcon: ICheck,
            iconColor: theme.Colors.Text.Success,
            onPressIcon: onPressIconSuccess,
            subTextColor: theme.Colors.Text.Success,
        },
    };

    const Icon = useMemo(() => {
        if (infoState === INPUT_STATUS.DEFAULT) {
            if (hasValue && isFocus && allowToClear) {
                return inputState[infoState].rightIcon;
            }
            return;
        }
        return inputState[infoState].rightIcon;
    }, [hasValue, infoState, isFocus, allowToClear]);

    const iconColor = inputState[infoState].iconColor;
    const onPressRightIcon = inputState[infoState].onPressIcon;
    const editable = mode === MODE.EDITABLE;

    useEffect(() => {
        inputColor.value =
            infoState === INPUT_STATUS.DEFAULT && (isFocus || hasValue)
                ? activeColor
                : inputState[infoState].color;
        subTextColor.value = inputState[infoState].subTextColor;
    }, [infoState, inputState, hasValue]);

    useEffect(() => {
        //just for  first mount time
        if (!hasValue && !isFocus) {
            isTextInputFocus.value = withTiming(0, { duration: DURATION });
        } else {
            isTextInputFocus.value = withTiming(1, { duration: DURATION });
        }
    }, [hasValue, isFocus]);

    const inputContainerStyles = useAnimatedStyle(() => {
        return {
            borderBottomColor: withTiming(inputColor.value),
        };
    });

    const labelStyle = useAnimatedStyle(() => {
        const translateY = interpolate(
            isTextInputFocus.value,
            [0, 1],
            [LABEL_INIT_POSITION, LABEL_TRANSFORM_POSITION]
        );
        const fontSize = interpolate(
            isTextInputFocus.value,
            [0, 1],
            [LABEL_BIG_FONT, LABEL_SMALL_FONT]
        );
        const lineHeight = interpolate(
            isTextInputFocus.value,
            [0, 1],
            [LABEL_BIG_LINE_HEIGHT, LABEL_SMALL_LINE_HEIGHT]
        );

        return {
            top: translateY,
            fontSize,
            lineHeight,
        };
    });

    const descTextStyle = useAnimatedStyle(() => {
        return {
            color: withTiming(subTextColor.value),
        };
    });

    const inputModeStyle = { opacity: mode === MODE.DISABLED ? 0.4 : 1 };

    return (
        <View style={[styles.container, containerStyle, inputModeStyle]}>
            {label && (
                <Animated.Text style={[styles.txtLabel, labelStyle]}>
                    {label}
                </Animated.Text>
            )}
            <Animated.View style={[styles.inputContainer, inputContainerStyles]}>
                <View style={[styles.inputWrapper]}>
                    <TextInput
                        {...props}
                        style={[styles.textInput, inputStyle]}
                        onBlur={onBlur}
                        onFocus={onFocus}
                        onChangeText={handleOnChangeText}
                        editable={editable}
                        value={value || inputValue}
                        ref={inputRef}
                    />
                    <Text style={[styles.textInput]}>VND</Text>
                </View>
                <View style={[styles.iconBox]}>
                    {rightIcon ? (
                        rightIcon()
                    ) : (
                        <>
                            {Icon && (
                                <Pressable onPress={onPressRightIcon}>
                                    <Icon fill={iconColor} />
                                </Pressable>
                            )}
                        </>
                    )}
                </View>
            </Animated.View>
            {subText && (
                <Animated.Text
                    style={[styles.subText, descTextStyle]}
                    entering={FadeIn}
                    exiting={FadeOut}
                >
                    {subText}
                </Animated.Text>
            )}
        </View>
    );
});

export { CurrencyInput };

const useStyles = createStyles((theme) => ({
    container: {
        marginTop: theme.Size.ms(16),
    },
    textInput: {
        ...theme.Typography.TextBody.Regular,
        // flex: 1,
        lineHeight: undefined,
        paddingVertical: theme.Size.vs(6),
    },
    inputContainer: {
        borderBottomWidth: 1,
        flexDirection: 'row',
        alignItems: 'center',
        justifyContent: 'space-between',
    },
    inputWrapper: {
        flexDirection: 'row',
        alignItems: 'center',
    },
    iconBox: {
        justifyContent: 'center',
        alignItems: 'center',
        marginLeft: theme.Size.hs(8),
        paddingRight: theme.Size.hs(8),
    },
    txtLabel: {
        ...theme.Typography.TextBody,
        color: theme.Colors.Text.Disable,
        position: 'absolute',
    },
    currency: {
        ...theme.Typography.TextBody.Regular,
        // justifyContent: 'center',
        // alignItems: 'center',
        textAlign: 'center',
        // marginLeft: theme.Size.hs(8),
        // paddingRight: theme.Size.hs(8),
    },
    subText: {
        marginTop: theme.Size.vs(8),
        ...theme.Typography.TextBody.Regular,
        color: theme.Colors.Text.Disable,
    },
}));
