import { TYPES } from '@src/di/types/types';
import { inject } from 'inversify';
import type { IGetInitLoanProposalRepository } from '@src/domain/interfaces/loan_collateral/get_init_loan_proposal';
import { GetInitLoanProposalPayload } from './get_init_loan_proposal_query';

export class GetInitLoanProposalHandler {
    private readonly _getInitLoanProposalRepository: IGetInitLoanProposalRepository;

    constructor(@inject(TYPES.IGetInitLoanProposalRepository) getInitLoanProposalRepository: IGetInitLoanProposalRepository) {
        this._getInitLoanProposalRepository = getInitLoanProposalRepository;
    }

    handle(dataReq: GetInitLoanProposalPayload) {
        return this._getInitLoanProposalRepository.getInitLoanProposal(dataReq);
    }
}
