import React from 'react';
import { type NativeStackNavigationProp, createNativeStackNavigator } from '@react-navigation/native-stack';

import GalleryScreen from '@presentation/gallery/screens/GalleryScreen';
import WeatherScreen from '@presentation/weather/screens';
import ProductsScreen from '../loan_products/ProductsScreen';
// REGISTER
import RegisterCVPScreen from '../loan_register/register_CVP/RegisterCVPScreen';
import RegisterConfirmScreen from '../loan_register/register_confirm/RegisterConfirmScreen';
import RegisterResultScreen from '../loan_register/register_result/RegisterResultScreen';
// COLLATERAL
import CollateralConfirmScreen from '../loan_collateral/collateral_confirm/CollateralConfirmScreen';
import CollateralResultScreen from '../loan_collateral/collateral_result/CollateralResultScreen';
import CollateralAccountsScreen from '../loan_collateral/collateral_accounts/CollateralAccountsScreen';
import CollateralAmountScreen from '../loan_collateral/collateral_amount/CollateralAmountScreen';
import { MiniAppNavigatorParams } from '@core/service';

export type MainStackParamList = {
    Weather: undefined;
    Gallery: undefined;

    products: undefined;

    // register
    register_cvp: undefined;
    register_confirm: undefined;
    register_result: undefined;

    // collateral
    collateral_accounts: undefined;
    collateral_amount: undefined;
    collateral_confirm: undefined;
    collateral_result: undefined;
};

export type MainStackNavigationProp = NativeStackNavigationProp<MainStackParamList>;
interface test extends MainStackNavigationProp, MiniAppNavigatorParams { };

const Main = createNativeStackNavigator<MainStackParamList>();

const MainNavigator = () => {
    return (
        <Main.Navigator screenOptions={{ headerShown: false }} initialRouteName='products'>
            <Main.Screen name='Weather' component={WeatherScreen} />
            <Main.Screen name='Gallery' component={GalleryScreen} />

            <Main.Screen name='products' component={ProductsScreen} />

            <Main.Screen name='register_cvp' component={RegisterCVPScreen} />
            <Main.Screen name='register_confirm' component={RegisterConfirmScreen} />
            <Main.Screen name='register_result' component={RegisterResultScreen} />

            <Main.Screen name='collateral_accounts' component={CollateralAccountsScreen} />
            <Main.Screen name='collateral_amount' component={CollateralAmountScreen} />
            <Main.Screen name='collateral_confirm' component={CollateralConfirmScreen} />
            <Main.Screen name='collateral_result' component={CollateralResultScreen} />
        </Main.Navigator>
    );
};

export default MainNavigator;
